const appState={state:requestedState,role:params.get('role')||defaults[requestedState]?.role||'reception',date:validDate?requestedDate:'2026-08-01',entries:baseEntries.map(x=>({...x})),selected:null,lastFocus:null,view:'day',alternative:false,weekAlternative:false,selectedSlot:null,filtersDirty:false};
const app=document.getElementById('app'),workspace=document.querySelector('.workspace'),drawer=document.getElementById('drawer'),modal=document.getElementById('modal'),backdrop=document.getElementById('modal-backdrop'),live=document.getElementById('live-region');
const esc=v=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const timeLabel=i=>`${String(8+Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`;
