function renderAll(){renderDay(appState.entries);renderAgenda(appState.entries);renderWeek()}
function showBanner(message,tone='warning'){const b=document.getElementById('system-banner');b.hidden=false;b.dataset.tone=tone;b.setAttribute('role',tone==='error'?'alert':'status');b.textContent=message}
function openDrawer(id,push=true){const e=appState.entries.find(x=>x.id===id)||baseEntries[1];appState.selected=id;drawer.hidden=false;workspace.classList.add('has-drawer');document.getElementById('drawer-status').textContent=e.kind==='overdue'?'Просрочена':e.status;document.getElementById('drawer-status').dataset.kind=e.kind;document.getElementById('drawer-title').textContent=`${e.pet} · ${e.time}–${e.end}`;document.getElementById('drawer-source').textContent=e.source;const overdue=e.kind==='overdue';document.getElementById('drawer-content').innerHTML=`<div class="drawer-body"><section class="drawer-section"><h3>Статус и SLA</h3><dl class="detail-grid"><dt>Статус</dt><dd>${overdue?'Просрочена':e.status}</dd>${e.sla?`<dt>${overdue?'Просрочено на':'До ответа'}</dt><dd>${overdue?'02:14':'00:38'}</dd>`:''}</dl></section><section class="drawer-section"><h3>Клиент и питомец</h3><dl class="detail-grid"><dt>Питомец</dt><dd>${e.pet}</dd><dt>Клиент</dt><dd>${e.owner||'—'}</dd><dt>Телефон</dt><dd>+7 921 555-14-20</dd></dl></section><section class="drawer-section"><h3>Запись</h3><dl class="detail-grid"><dt>Услуга</dt><dd>${e.service}</dd><dt>Сотрудник</dt><dd>${e.staff}</dd><dt>Время</dt><dd>1 августа, ${e.time}–${e.end}</dd><dt>Цена</dt><dd>${e.price||'—'}</dd></dl></section><section class="drawer-section"><h3>История</h3><ol class="history"><li>14:02 · заявка создана владельцем</li><li>14:04 · назначена сотруднику</li></ol></section></div>${['pending','overdue'].includes(e.kind)?`<footer class="drawer-footer" aria-label="Действия с заявкой"><button class="primary-button" data-action="confirm">Подтвердить</button><button class="secondary-button" data-action="alternative">Другое время</button><button class="secondary-button destructive" data-action="reject">Отклонить</button></footer>`:`<footer class="drawer-footer"><button class="secondary-button" data-action="open-client">Открыть клиента</button></footer>`}`;renderDay(appState.entries);if(push)setUrl(e.kind==='confirmed'?'confirmed-appointment':'pending-request');requestAnimationFrame(()=>document.getElementById('drawer-title')?.focus({preventScroll:true}))}
function closeDrawer(){drawer.hidden=true;workspace.classList.remove('has-drawer');appState.selected=null;renderAll();appState.lastFocus?.focus()}
function openModal(title,body,footer=''){appState.lastFocus=document.activeElement;document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=`<div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}`;modal.hidden=false;backdrop.hidden=false;requestAnimationFrame(()=>document.getElementById('modal-content').querySelector('input,select,textarea,button')?.focus())}
function closeModal(){modal.hidden=true;backdrop.hidden=true;appState.lastFocus?.focus()}
function manualModal(invalid=false){const body=`<form id="manual-form"><div class="form-columns"><section class="form-column"><h3>Клиент / питомец</h3><label class="field"><span>Клиент</span><input name="client" type="search" value="Анна Ковалева" aria-describedby="client-result"></label><div id="client-result" class="client-result"><strong>Анна Ковалева</strong><span>+7 921 555-14-20</span><button type="button" class="text-button" data-action="quick-client">Создать нового клиента</button></div><label class="field"><span>Питомец</span><select name="pet"><option>Барсик</option><option>Марс</option></select></label><label class="field"><span>Комментарий</span><textarea name="comment" placeholder="Пожелания клиента"></textarea></label></section><section class="form-column"><h3>Запись / время</h3><label class="field"><span>Услуга</span><select name="service"><option>Первичный приём терапевта</option><option>Диагностика</option></select></label><label class="field"><span>Врач</span><select name="staff"><option>Анна Иванова</option><option>Мария Смирнова</option></select></label><label class="field"><span>Дата</span><input name="date" value="1 августа 2026" readonly></label><div><span class="field-label">Доступное время</span><div class="slot-picker">${['14:30','15:30','16:00'].map(t=>`<button type="button" class="slot-choice" data-action="manual-time" data-time="${t}" aria-pressed="false">${t}</button>`).join('')}</div><input type="hidden" name="time"><p class="field-error" ${invalid?'':'hidden'}>Выберите доступное время</p></div><div class="price-control"><span>Цена из услуги</span><strong>2 500 ₽</strong></div><div id="booking-summary" class="booking-summary"><h3>Резюме</h3><p>Барсик · Первичный приём терапевта</p><p>Анна Иванова · <span>время не выбрано</span></p><p><strong>2 500 ₽</strong></p></div></section></div></form>`;openModal('Новая запись',body,`<button class="secondary-button" data-action="close-modal" aria-label="Отмена">Отмена</button><button class="primary-button" id="manual-submit" type="submit" form="manual-form" disabled>Создать запись</button>`);if(invalid)setUrl('manual-booking-invalid')}
function alternativeModal(){appState.alternative=true;const body=`<div class="alternative-layout"><section class="availability"><div class="availability-head">Доступность журнала · 1 августа</div><div class="availability-list">${[{t:'14:30',s:'Анна Иванова'},{t:'15:00',s:'Илья Петров',off:true},{t:'16:00',s:'Мария Смирнова'}].map(x=>`<button class="availability-slot" data-action="alternative-slot" data-time="${x.t}" data-staff="${x.s}" aria-pressed="false" ${x.off?'disabled':''}><strong>${x.t}</strong><span>${x.s}</span><span>${x.off?'Занято':'Доступно'}</span></button>`).join('')}</div></section><aside class="comparison"><div class="comparison-card"><h3>Исходная заявка</h3><p><strong>1 августа, 10:30</strong><br>Анна Иванова</p><p>Первичный приём<br>2 500 ₽</p></div><div id="alternative-review" class="comparison-card"><h3>Предлагаем</h3><p>Выберите доступный слот в журнале</p></div><label class="field"><span>Причина</span><select><option>Врач занят в исходное время</option><option>По просьбе владельца</option></select></label></aside></div>`;openModal('Выбрать другое время из журнала',body,`<button class="secondary-button" data-action="close-modal">Отмена</button><button class="primary-button" data-action="send-alternative" disabled>Отправить владельцу</button>`);setUrl('alternative-selection')}
function rejectModal(){openModal('Отклонить заявку',`<p>Барсик · 1 августа, 10:30</p><label class="field"><span>Причина</span><textarea>Нет доступного врача</textarea></label>`,`<button class="secondary-button" data-action="close-modal">Отмена</button><button class="primary-button" data-action="complete-reject">Отклонить заявку</button>`)}
function toggleView(view,state){appState.view=view;const week=view==='week';document.getElementById('day-grid').hidden=week;document.getElementById('week-grid').hidden=!week;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));document.querySelector('.filters fieldset:first-of-type').hidden=week;if(week&&!appState.weekAlternative)closeDrawer();if(state)setUrl(state);renderWeek()}
function openSearch(value=''){appState.lastFocus=document.activeElement;const p=document.getElementById('search-panel');p.hidden=false;backdrop.hidden=false;const input=document.getElementById('search-input');input.value=value;renderSearch(value);input.focus()}
function renderSearch(q){const matches=appState.entries.filter(e=>`${e.pet} ${e.owner} ${e.staff}`.toLowerCase().includes(q.toLowerCase()));document.getElementById('search-results').innerHTML=matches.length?matches.map(e=>`<button class="search-result" data-search-entry="${e.id}"><strong>${e.pet}</strong><br>${e.time} · ${e.service} · ${e.staff}</button>`).join(''):'<p class="modal-body">Ничего не найдено</p>'}
function closeSearch(){document.getElementById('search-panel').hidden=true;backdrop.hidden=true;appState.lastFocus?.focus()}
function renderState(){if(!STATES.includes(requestedState))return controlledError(`Неизвестное состояние: ${requestedState}`);if(!ROLES.includes(appState.role))return controlledError(`Неизвестная роль: ${appState.role}`);app.dataset.state=requestedState;app.dataset.role=appState.role;document.getElementById('role-label').textContent={reception:'Администратор',admin:'Управляющий',veterinarian:'Ветеринар',"multi-role":'Управляющий · администратор'}[appState.role];renderAll();const c=defaults[requestedState]||{};if(c.banner==='error')showBanner('Не удалось загрузить журнал. Ошибка не означает, что записей нет. Повторите попытку.','error');if(c.banner==='stale')showBanner('Не удалось обновить данные. Показана последняя доступная версия от 14:32.','warning');if(c.conflict)showBanner('Это время уже занято. Выберите другой доступный интервал.','error');if(c.empty||c.noStaff){document.querySelector('.sla-bar').hidden=true;document.querySelector('.mobile-urgent').hidden=true;document.getElementById('day-grid').hidden=true;document.getElementById('agenda').hidden=true;const e=document.getElementById('empty-state');e.hidden=false;if(c.noStaff){e.querySelector('h2').textContent='Для этой даты не настроено расписание сотрудников';e.querySelector('p').textContent='Проверьте рабочие часы или выберите другую дату.'}}if(c.forbidden){showBanner('У вас нет доступа к этой локации.','error');document.querySelectorAll('.workspace,.sla-bar,.mobile-urgent,.toolbar,.mobile-date,.bottom-nav,.sidebar nav').forEach(x=>x.hidden=true);return}if(c.filters){document.querySelector('[name=status][value=pending]').checked=true;document.getElementById('filter-count').textContent='1';document.querySelector('[data-action=reset-filters]').hidden=false}if(c.week||c.weekAlternative){appState.weekAlternative=!!c.weekAlternative;toggleView('week',null)}if(c.selected)openDrawer(c.selected,false);if(c.alternative)alternativeModal();if(c.reject)rejectModal();if(c.manual)manualModal(c.invalid);if(c.search!==undefined)openSearch(c.search)}
document.addEventListener('click',e=>{const entry=e.target.closest('[data-entry-id]');if(entry){appState.lastFocus=entry;openDrawer(entry.dataset.entryId);return}const search=e.target.closest('[data-search-entry]');if(search){closeSearch();openDrawer(search.dataset.searchEntry);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close-drawer')closeDrawer();else if(a==='open-first'){appState.lastFocus=b;openDrawer('demo-request-barsik')}else if(a==='close-modal')closeModal();else if(a==='manual-booking'||a==='free-slot'){manualModal();if(b.dataset.time)requestAnimationFrame(()=>document.querySelector(`[data-action=manual-time][data-time="${b.dataset.time}"]`)?.click())}else if(a==='manual-time'){document.querySelectorAll('[data-action=manual-time]').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');const form=document.getElementById('manual-form');form.elements.time.value=b.dataset.time;form.querySelector('.field-error').hidden=true;document.getElementById('manual-submit').disabled=false;document.querySelector('#booking-summary span').textContent=`1 августа, ${b.dataset.time}–${b.dataset.time==='14:30'?'15:00':'16:30'}`;announce(`Выбрано время ${b.dataset.time}`)}else if(a==='alternative')alternativeModal();else if(a==='alternative-slot'){document.querySelectorAll('[data-action=alternative-slot]').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');appState.selectedSlot={time:b.dataset.time,staff:b.dataset.staff};document.getElementById('alternative-review').innerHTML=`<h3>Было → предлагаем</h3><p><strong>10:30 · Анна Иванова</strong></p><p><strong>${b.dataset.time} · ${b.dataset.staff}</strong></p><p>Цена: 2 500 ₽</p>`;document.querySelector('[data-action=send-alternative]').disabled=false;announce(`Выбрано ${b.dataset.time}, ${b.dataset.staff}`)}else if(a==='send-alternative'){const entry=appState.entries.find(x=>x.id==='demo-request-barsik');entry.kind='alternative';entry.status='Ожидает решения владельца';entry.time=appState.selectedSlot.time;entry.staff=appState.selectedSlot.staff;closeModal();openDrawer(entry.id,false);setUrl('owner-decision-pending')}else if(a==='reject')rejectModal();else if(a==='complete-reject'){const entry=appState.entries.find(x=>x.id==='demo-request-barsik');entry.kind='rejected';entry.status='Отклонена';closeModal();openDrawer(entry.id,false)}else if(a==='confirm'){const entry=appState.entries.find(x=>x.id==='demo-request-barsik');entry.kind='confirmed';entry.status='Подтверждена';delete entry.sla;openDrawer(entry.id,false);setUrl('confirmed-appointment')}else if(a==='open-search')openSearch();else if(a==='close-search')closeSearch();else if(a==='open-filters'){appState.lastFocus=b;document.getElementById('filters').classList.add('open');backdrop.hidden=false;document.querySelector('[data-action=close-filters]').focus()}else if(a==='close-filters'){document.getElementById('filters').classList.remove('open');backdrop.hidden=true;appState.lastFocus?.focus()}else if(a==='collapse-filters'){workspace.classList.toggle('filters-collapsed');b.setAttribute('aria-pressed',String(workspace.classList.contains('filters-collapsed')))}else if(a==='reset-filters'){document.querySelectorAll('.filters input').forEach(x=>x.checked=x.value==='all');document.getElementById('filter-count').textContent='';b.hidden=true;document.querySelector('[data-action=apply-filters]').disabled=true;renderAll()}else if(a==='apply-filters'){b.disabled=true;document.getElementById('filters').classList.remove('open');backdrop.hidden=true;announce('Фильтры применены')}else if(a==='refresh'){showBanner('Журнал обновлён в 14:34.','info')}else if(a==='week-slot'){appState.selectedSlot={time:b.dataset.time,staff:'Анна Иванова'};b.setAttribute('aria-pressed','true');announce(`Выбран свободный интервал ${b.dataset.day}, ${b.dataset.time}`)}else if(a==='quick-client')announce('Создание клиента показано в отдельном потоке прототипа')});
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='week-slot'){document.querySelectorAll('.week-free[aria-pressed=true]').forEach(x=>{if(x!==button)x.removeAttribute('aria-pressed')});appState.selectedSlot={time:button.dataset.time,day:button.dataset.day,staff:'Анна Иванова'};const selected=document.getElementById('week-selected-slot');if(selected)selected.textContent=`${button.dataset.day} · ${button.dataset.time} · Анна Иванова`;const review=document.querySelector('[data-action=review-week-alternative]');if(review)review.disabled=false}else if(button.dataset.action==='review-week-alternative'){openModal('Проверить другое время',`<div class="comparison-card"><h3>Было</h3><p>Пт 1 · 10:30 · Анна Иванова</p><h3>Предлагаем</h3><p><strong>${appState.selectedSlot.day} · ${appState.selectedSlot.time} · ${appState.selectedSlot.staff}</strong></p><p>Первичный приём терапевта · 2 500 ₽</p></div>`,`<button class="secondary-button" data-action="close-modal">Назад</button><button class="primary-button" data-action="send-alternative">Отправить владельцу</button>`)}});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>toggleView(b.dataset.view,b.dataset.view==='week'?'week-view':'reception-ready')));
document.querySelectorAll('.filters input').forEach(i=>i.addEventListener('change',()=>{document.querySelector('[data-action=apply-filters]').disabled=false;const active=[...document.querySelectorAll('.filters input:checked')].filter(x=>x.value!=='all').length;document.getElementById('filter-count').textContent=active||'';document.querySelector('[data-action=reset-filters]').hidden=!active}));
document.getElementById('search-input').addEventListener('input',e=>renderSearch(e.target.value));
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id!=='manual-form')return;const data=new FormData(e.target);if(!data.get('time')){e.target.querySelector('.field-error').hidden=false;announce('Выберите доступное время');return}closeModal();announce(`Запись на ${data.get('time')} создана в демонстрационном прототипе`)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!modal.hidden)closeModal();else if(!document.getElementById('search-panel').hidden)closeSearch();else if(document.getElementById('filters').classList.contains('open')){document.getElementById('filters').classList.remove('open');backdrop.hidden=true;appState.lastFocus?.focus()}else if(!drawer.hidden)closeDrawer()}});
window.addEventListener('popstate',()=>location.reload());renderState();
